#include <bits/stdc++.h>
using namespace std;
struct DSU{vector<int>p,s;DSU(int n):p(n),s(n,1){iota(p.begin(),p.end(),0);}int f(int x){return p[x]==x?x:p[x]=f(p[x]);}bool join(int a,int b){a=f(a);b=f(b);if(a==b)return 0;if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];return 1;}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n,m;cin>>n>>m;int N=n*m;vector<int>g(N);for(int&i:g)cin>>i;int q;cin>>q;vector<int>hit(q),dead(N);for(int i=0,r,c;i<q;i++){cin>>r>>c;hit[i]=(--r)*m+(--c);dead[hit[i]]=1;}DSU d(N);vector<char>on(N);long long E=0,V=0,C=0;int dr[4]={-1,0,1,0},dc[4]={0,1,0,-1},bit[4]={1,2,4,8};auto add=[&](int v){on[v]=1;V++;C++;int r=v/m,c=v%m;for(int z=0;z<4;z++){int rr=r+dr[z],cc=c+dc[z];if(rr<0||rr>=n||cc<0||cc>=m)continue;int u=rr*m+cc;if(on[u]&&(g[v]&bit[z])&&(g[u]&bit[(z+2)%4])){E++;if(d.join(v,u))C--;}}};for(int v=0;v<N;v++)if(g[v]&&!dead[v])add(v);vector<long long>ans(q);for(int i=q-1;i>=0;i--){ans[i]=E-V+C;add(hit[i]);}for(int i=0;i<q;i++)cout<<ans[i]<<(i+1==q?'\n':' ');if(!q)cout<<'\n';}}
